assert.equal(git('rev-parse','HEAD').toString().trim(),m.parent_commit);
const expected=[".agent/tasks/production-readiness-20260917/evidence.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-build-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-causal-red-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-final-baseline-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-full-unit-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-green-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-integrity-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-manifest-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-notes-20260921.md",".agent/tasks/production-readiness-20260917/evidence/agent-requests-quality-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-quality-final-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-red-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-review-baseline-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-review-green-20260921.json",".agent/tasks/production-readiness-20260917/evidence/agent-requests-verified-red-20260921.json",".agent/tasks/production-readiness-20260917/evidence/local-disk-reconciliation-20260921.md",".agent/tasks/production-readiness-20260917/support/agent_requests_baseline_vitest.config.mjs","docs/production-readiness/02-audit-backlog.md","docs/production-readiness/05-ux-review.md","docs/production-readiness/06-change-log.md","docs/production-readiness/09-residual-risks.md","docs/production-readiness/COMMANDS.md","docs/production-readiness/DECISIONS.md","docs/production-readiness/HANDOFF.md","docs/production-readiness/PROGRESS.md","frontend/src/pages/dashboard/AgentBlueprintsWorkspace.requests.test.tsx","frontend/src/pages/dashboard/AgentBlueprintsWorkspace.schedule.test.tsx","frontend/src/pages/dashboard/AgentBlueprintsWorkspace.tsx"];
const staged=git('diff','--cached','--name-only','-z').toString().split('\0').filter(Boolean).sort();
assert.deepEqual(staged,expected);
for(const path of expected)assert.ok(fs.readFileSync(path).equals(git('show',':'+path)),'Index differs: '+path);
for(const row of [...m.source_hashes,...m.captures,...m.protected_records])assert.equal(hash(fs.readFileSync(row.path)),row.sha256,'Hash differs: '+row.path);
const ev=JSON.parse(fs.readFileSync(base+'/evidence.json')),prior=JSON.parse(git('show','HEAD:'+base+'/evidence.json').toString());
assert.deepEqual(ev.acceptance_criteria,prior.acceptance_criteria);
assert.equal(ev.overall_status,'FAIL');
for(const row of m.protected_records)assert.ok(fs.readFileSync(row.path).equals(git('show','HEAD:'+row.path)));
const strip=text=>text.replace(/\x1b\[[0-9;]*m/g,'');
const read=name=>JSON.parse(fs.readFileSync(base+'/evidence/agent-requests-'+name+'-20260921.json'));
for(const name of ['review-green','quality-final','build','integrity','full-unit']){const r=read(name);assert.equal(r.exit_code,0);assert.equal(r.timed_out,false);assert.equal(r.stdout_truncated,false);assert.equal(r.stderr_truncated,false);}
const red=read('review-baseline');assert.equal(red.exit_code,1);assert.match(strip(red.stdout),/7 failed.*3 passed/);assert.ok(red.stdout.includes(m.source_hashes.find(x=>x.path.endsWith('.requests.test.tsx')).sha256));
assert.match(strip(read('review-green').stdout),/15 passed/);
assert.match(strip(read('full-unit').stdout),/824 passed/);
assert.match(strip(read('full-unit').stdout),/139 passed/);
git('diff','--cached','--check');
const scannerConfig='/private/tmp/localos-git-history-verified-20260921.qZcoBF/scanner-defaults.toml';
assert.match(fs.readFileSync(scannerConfig,'utf8'),/useDefault\s*=\s*true/);
const diff=git('diff','--cached','--binary','--no-ext-diff');
const scan=cp.spawnSync('/usr/local/bin/gitleaks',['stdin','--config',scannerConfig,'--ignore-gitleaks-allow','--gitleaks-ignore-path=/dev/null','--redact=100','--no-banner','--no-color'],{input:diff,encoding:'utf8',maxBuffer:1000000});
if(scan.status!==0){process.stdout.write(scan.stdout||'');process.stderr.write(scan.stderr||'');throw Error('Strict staged scan failed');}
console.log(JSON.stringify({result:'PASS',owned_files:staged.length,staged_bytes:diff.length,source_hashes:m.source_hashes.length,captures:m.captures.length,strict_staged_scan:'PASS',original_criteria_and_records:'preserved'}));
